css:
.fx-pt{width:min(1000px,100%);display:grid;gap:2em;justify-items:center;text-align:center}
.fx-pt h2{font-size:clamp(2em,4.6vw,3em)}.fx-pt .sub{opacity:.65;margin-top:.5em}
.fx-pt .sw{display:flex;align-items:center;gap:.9em;font-weight:600;font-size:.95em}
.fx-pt .sw .l{opacity:.55;transition:opacity .3s}.fx-pt:not(.yr) .sw .lm,.fx-pt.yr .sw .ly{opacity:1}
.fx-pt .sw button{all:unset;box-sizing:border-box;width:3.4em;height:1.9em;border-radius:99px;background:var(--border);position:relative;cursor:pointer;transition:background calc(.3s/var(--speed))}
.fx-pt .sw button::after{content:"";position:absolute;top:.2em;left:.2em;width:1.5em;height:1.5em;border-radius:50%;background:var(--surface);box-shadow:0 2px 6px rgba(0,0,0,.25);transition:transform calc(.3s/var(--speed)) cubic-bezier(.3,1.4,.5,1)}
.fx-pt .sw button[aria-checked=true]{background:var(--primary)}.fx-pt .sw button[aria-checked=true]::after{transform:translateX(1.5em)}
.fx-pt .sw button:focus-visible{outline:2px solid var(--accent);outline-offset:3px}
.fx-pt .save{padding:.25em .7em;border-radius:99px;background:color-mix(in srgb,var(--accent) 18%,transparent);color:var(--text);font-size:.78em;font-weight:700;border:1px solid color-mix(in srgb,var(--accent) 50%,transparent)}
.fx-pt .plans{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1.2em;width:100%;text-align:left}
.fx-pt .plan{padding:1.6em;border:1px solid var(--border);border-radius:var(--radius);background:color-mix(in srgb,var(--surface) 94%,var(--text));display:grid;gap:1em;align-content:start}
.fx-pt .plan.pop{border-color:var(--primary);box-shadow:0 0 0 1px var(--primary)}
.fx-pt .plan h3{font-size:1.25em}.fx-pt .plan .d{opacity:.65;font-size:.9em}
.fx-pt .price{display:flex;align-items:baseline;gap:.3em;min-height:3.2em;flex-wrap:wrap}
.fx-pt .price b{font:600 2.8em/1 var(--font-heading);font-variant-numeric:tabular-nums}.fx-pt .price small{opacity:.6;font-size:.85em}
.fx-pt .price .y{display:none}.fx-pt.yr .price .y{display:inline-flex;align-items:baseline;gap:.3em;flex-wrap:wrap}.fx-pt.yr .price .m{display:none}
.fx-pt .price .m,.fx-pt .price .y{animation:fxptpop calc(.45s/var(--speed)) cubic-bezier(.2,.8,.2,1)}
.fx-pt .bill{font-size:.8em;opacity:.55;margin-top:-.6em;min-height:1.2em}
.fx-pt ul{list-style:none;margin:0;padding:0;display:grid;gap:.55em;font-size:.93em}
.fx-pt li{display:flex;gap:.6em}.fx-pt li::before{content:"✓";color:var(--accent);font-weight:800}
.fx-pt .btn{display:block;text-align:center;padding:.85em 1em;border-radius:var(--radius);font-weight:700;text-decoration:none;border:1.5px solid var(--primary);color:var(--primary);transition:background .25s,color .25s}
.fx-pt .btn:hover,.fx-pt .pop .btn{background:var(--primary);color:var(--on-primary)}.fx-pt .pop .btn:hover{opacity:.9}
.fx-pt .btn:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
@keyframes fxptpop{from{opacity:0;transform:translateY(.4em)}to{opacity:1;transform:none}}
@media(max-width:820px){.fx-pt .plans{grid-template-columns:1fr}}
@media(prefers-reduced-motion:reduce){.fx-pt .price .m,.fx-pt .price .y{animation:none}.fx-pt .sw button,.fx-pt .sw button::after{transition:none}}
/* touch: :hover mirrored as .is-tap */
.fx-pt .btn.is-tap{background:var(--primary);color:var(--on-primary)}
.fx-pt .pop .btn.is-tap{opacity:.9}

js:
(function(){document.querySelectorAll('.fx-pt').forEach(function(r){var b=r.querySelector('.sw button');
function set(y){r.classList.toggle('yr',y);b.setAttribute('aria-checked',y);r.querySelectorAll('.bill span').forEach(function(s){s.textContent=y?'Billed annually':'Billed monthly'})}
b.addEventListener('click',function(){set(b.getAttribute('aria-checked')!=='true')});
r.querySelectorAll('.sw .l').forEach(function(l){l.style.cursor='pointer';l.addEventListener('click',function(){set(l.classList.contains('ly'))})})})})();
/* fx-touch */
(function(){if(window.__fxTap)return;window.__fxTap=1;var cur=[];function clr(){cur.forEach(function(e){e.classList.remove('is-tap')});cur=[]}
document.addEventListener('pointerdown',function(e){if(e.pointerType!=='touch')return;clr();var n=e.target.closest&&e.target.closest('.fx');if(!n)return;for(var el=e.target;el&&el!==n.parentNode;el=el.parentNode){if(el.classList){el.classList.add('is-tap');cur.push(el)}}},{passive:true});
document.addEventListener('pointerup',function(){setTimeout(clr,1400)},{passive:true})})();
